function registerBoardsApi(router::HTTP.Router, impl; path_prefix::String="", optional_middlewares...)
    HTTP.register!(router, "POST", path_prefix * "/boards/{board_id}/sections", OpenAPI.Servers.middleware(impl, board_sections_create_read, board_sections_create_validate, board_sections_create_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/boards/{board_id}/sections/{section_id}", OpenAPI.Servers.middleware(impl, board_sections_delete_read, board_sections_delete_validate, board_sections_delete_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/boards/{board_id}/sections", OpenAPI.Servers.middleware(impl, board_sections_list_read, board_sections_list_validate, board_sections_list_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/boards/{board_id}/sections/{section_id}/pins", OpenAPI.Servers.middleware(impl, board_sections_list_pins_read, board_sections_list_pins_validate, board_sections_list_pins_invoke; optional_middlewares...))
    HTTP.register!(router, "PATCH", path_prefix * "/boards/{board_id}/sections/{section_id}", OpenAPI.Servers.middleware(impl, board_sections_update_read, board_sections_update_validate, board_sections_update_invoke; optional_middlewares...))
    HTTP.register!(router, "POST", path_prefix * "/boards", OpenAPI.Servers.middleware(impl, boards_create_read, boards_create_validate, boards_create_invoke; optional_middlewares...))
    HTTP.register!(router, "DELETE", path_prefix * "/boards/{board_id}", OpenAPI.Servers.middleware(impl, boards_delete_read, boards_delete_validate, boards_delete_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/boards/{board_id}", OpenAPI.Servers.middleware(impl, boards_get_read, boards_get_validate, boards_get_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/boards", OpenAPI.Servers.middleware(impl, boards_list_read, boards_list_validate, boards_list_invoke; optional_middlewares...))
    HTTP.register!(router, "GET", path_prefix * "/boards/{board_id}/pins", OpenAPI.Servers.middleware(impl, boards_list_pins_read, boards_list_pins_validate, boards_list_pins_invoke; optional_middlewares...))
    HTTP.register!(router, "PATCH", path_prefix * "/boards/{board_id}", OpenAPI.Servers.middleware(impl, boards_update_read, boards_update_validate, boards_update_invoke; optional_middlewares...))
    return router
end
